import { useEffect } from "react";
import ULThemeCard from "@/components/ULThemeCard";
import ULThemePageLayout from "@/components/ULThemePageLayout";
import ULThemeSeparator from "@/components/ULThemeSeparator";
import { useProductBrandingByName } from "@/hooks/useProductBranding";
import { extractTokenValue } from "@/utils/helpers/tokenUtils";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import AlternativeLogins from "./components/AlternativeLogins";
import Footer from "./components/Footer";
import Header from "./components/Header";
import SignupForm from "./components/SignupForm";
import { useSignupManager } from "./hooks/useSignupManager";

// Floating particles for B2B2C consumer apps
function ConsumerParticles() {
  const particles = Array.from({ length: 15 }, (_, i) => ({
    id: i,
    left: `${Math.random() * 100}%`,
    delay: `${Math.random() * 8}s`,
    duration: `${12 + Math.random() * 8}s`,
    size: `${6 + Math.random() * 10}px`,
    opacity: 0.1 + Math.random() * 0.15,
  }));

  return (
    <div className="acul-consumer-particles">
      {particles.map((particle) => (
        <div
          key={particle.id}
          className="acul-consumer-particle"
          style={{
            left: particle.left,
            animationDelay: particle.delay,
            animationDuration: particle.duration,
            width: particle.size,
            height: particle.size,
            opacity: particle.opacity,
          }}
        />
      ))}
    </div>
  );
}

// Welcome badge for B2B2C signup
function WelcomeBadge({ name }: { name: string }) {
  return (
    <div className="acul-rewards-badge">
      <span className="acul-rewards-icon">🎉</span>
      <span>Join {name}</span>
    </div>
  );
}

// Helper to detect B2B2C product
function getProductContext(product: string | undefined): {
  isB2B2C: boolean;
  displayName: string;
} {
  if (!product) {
    return { isB2B2C: false, displayName: "" };
  }

  const b2b2cProducts: Record<string, string> = {
    "acme-rewards": "Acme Rewards",
    "beta-rewards": "Beta Rewards",
    "gamma-rewards": "Gamma Rewards",
  };

  if (b2b2cProducts[product]) {
    return { isB2B2C: true, displayName: b2b2cProducts[product] };
  }

  return { isB2B2C: false, displayName: "" };
}

function SignupScreen() {
  const { signup, texts, alternateConnections, locales } = useSignupManager();

  // Get product from SDK or URL params (for dev testing)
  const devProduct =
    typeof window !== "undefined"
      ? new URLSearchParams(window.location.search).get("ext-product")
      : null;

  // Access product from signup instance if available
  const sdkProduct = (signup as { screen?: { untrustedData?: { authorizationParams?: { 'ext-product'?: string } } } })
    ?.screen?.untrustedData?.authorizationParams?.['ext-product'];

  const activeProduct = sdkProduct || devProduct || undefined;
  const productBranding = useProductBrandingByName(activeProduct);
  const { isB2B2C, displayName } = getProductContext(activeProduct);

  // Apply theme classes to body
  useEffect(() => {
    document.body.classList.remove("acul-b2b-theme", "acul-b2b2c-theme");

    if (isB2B2C) {
      document.body.classList.add("acul-b2b2c-theme");
    }

    return () => {
      document.body.classList.remove("acul-b2b2c-theme");
    };
  }, [isB2B2C]);

  const showSeparator = alternateConnections && alternateConnections.length > 0;
  const separatorText = texts?.separatorText || locales.page.separator;
  document.title = texts?.pageTitle || locales.page.title;

  applyAuth0Theme(signup, productBranding);

  const socialLoginAlignment = extractTokenValue(
    "--ul-theme-widget-social-buttons-layout"
  );

  const renderSocialLogins = (alignment: "top" | "bottom") => (
    <>
      {alignment === "bottom" && showSeparator && (
        <ULThemeSeparator text={separatorText} />
      )}
      <AlternativeLogins />
      {alignment === "top" && showSeparator && (
        <ULThemeSeparator text={separatorText} />
      )}
    </>
  );

  return (
    <ULThemePageLayout className="theme-universal">
      {/* B2B2C Consumer background */}
      {isB2B2C && <ConsumerParticles />}

      <ULThemeCard
        className={`w-full max-w-[400px] gap-0 ${isB2B2C ? "acul-b2b2c-card" : ""}`}
      >
        {/* B2B2C welcome badge */}
        {isB2B2C && displayName && (
          <div className="flex justify-center pt-4">
            <WelcomeBadge name={displayName} />
          </div>
        )}

        <Header />
        {socialLoginAlignment === "top" && renderSocialLogins("top")}
        <SignupForm />
        <Footer />
        {socialLoginAlignment === "bottom" && renderSocialLogins("bottom")}

        {/* B2B2C benefits messaging */}
        {isB2B2C && (
          <div className="acul-b2b2c-footer">
            <p>🎁 Get 100 bonus points on signup!</p>
          </div>
        )}
      </ULThemeCard>
    </ULThemePageLayout>
  );
}

export default SignupScreen;
